<style>
	        .sticky-button {
            position: fixed;
            top: 45%; /* Vertical center */
            right: 0; /* Align to the right edge */
            transform: rotate(-90deg) translateY(-50%); /* Rotate text and center vertically */
            transform-origin: right center; /* Anchor the rotation to the right center */
            background-color: #2c409f; /* Button background color */
            color: white; /* Text color */
            padding: 5px 10px;
            border: none;
            border-radius: 5px;
            text-align: center;
            cursor: pointer;
            box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
            z-index: 1000; /* Ensures it stays on top */
            text-decoration: none; /* Remove underline */
				font-size: 16px;
        }

        .sticky-button:hover {
            background-color: #313131; /* Change background color on hover */
		     color: #ffffff;
        }

        /* ===== Header action buttons (Login + Book a Demo) ===== */
        .hdr-btns {
            display: flex;
            align-items: center;
            gap: 12px;
        }
        .hdr-btn {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            font-family: Poppins, sans-serif;
            font-size: 15px;
            font-weight: 600;
            line-height: 1;
            padding: 11px 22px;
            border-radius: 8px;
            text-decoration: none;
            white-space: nowrap;
            cursor: pointer;
            transition: all .25s ease;
        }
        /* Secondary = Login */
        .hdr-btn-secondary {
            color: #2c409f !important;
            background: transparent;
            border: 1.5px solid #2c409f;
        }
        .hdr-btn-secondary:hover {
            background: #2c409f;
            color: #fff !important;
            /* box-shadow: 0 6px 18px rgba(44,64,159,.28); */
        }
        /* Primary = Book a Demo */
        .hdr-btn-primary {
            color: #fff !important;
            background: #2c409f;
            border: 1.5px solid #2c409f;
            /* box-shadow: 0 6px 18px rgba(44,64,159,.30); */
        }
        .hdr-btn-primary:hover {
            background: #4f3aa3;
            border-color: #4f3aa3;
            color: #fff !important;
            transform: translateY(-2px);
            box-shadow: 0 10px 24px rgba(44,64,159,.40);
        }
        /* Mobile menu buttons */
        .hdr-btns-mobile {
            display: flex;
            gap: 12px;
            padding: 18px 20px 6px;
        }
        .hdr-btns-mobile .hdr-btn { flex: 1 1 0; }

        @media (max-width: 1200px) {
            /* hide the desktop header buttons, mobile menu has its own */
            .wgl-site-header .hdr-btns,
            .wgl-sticky-header .hdr-btns { display: none; }
        }
        @media (max-width: 480px) {
            .hdr-btn { font-size: 14px; padding: 10px 16px; }
        }
</style>
