<script>
    function closeAd() {
        document.querySelector('.Ad').style.display = 'none';
        localStorage.setItem('adClosed', Date.now());
    }

    function shouldShowAd() {
        const adClosedTime = localStorage.getItem('adClosed');
        if (adClosedTime) {
            const now = Date.now();
            const doNotAppearIn = 3 * 60 * 1000;
            if (now - adClosedTime < doNotAppearIn) {
                return false;
            }
        }
        return true;
    }
    document.addEventListener('DOMContentLoaded', function() {
        if (shouldShowAd()) {
            const adPopup = document.querySelector('.Ad');
            adPopup.style.display = 'flex';
            adPopup.style.animation = 'flip 1s linear'; 
        }
    });
</script>  ---->
